const check=(label:string,expression:string,feedback:string):JSCheck=>({label,expression:'(()=>{try{return ('+expression+');}catch{return false;}})()',expected:true,feedback});
const conferirMedias=(casos:string)=>'('+casos+').every(([a,b,c])=>{const obtido=mediaTres(a,b,c),esperado=(a+b+c)/3;return typeof obtido==="number"&&Number.isFinite(obtido)&&Math.abs(obtido-esperado)<=Number.EPSILON*4*Math.max(1,Math.abs(esperado));})';
const javascript:Record<string,JSSpec>={
 'async-corrigir-resposta':{checks:[
  {label:'Espera a resposta e devolve o corpo, chamando cada operação uma vez.',aguardar:true,expected:true,expression:'(async()=>{let consultas=0,leituras=0;const dado={nome:"Lia"};const resultado=lerResposta(()=>{consultas++;return Promise.resolve().then(()=>({ok:true,status:200,json(){leituras++;return Promise.resolve().then(()=>dado);}}));});if(!resultado||typeof resultado.then!=="function")return false;return await resultado===dado&&consultas===1&&leituras===1;})()',feedback:'Aguarde a resposta antes de ler ok e devolva o corpo resolvido. Chamar a operação não basta: o retorno precisa chegar ao chamador.'},
  {label:'Preserva dados vazios, falsy e variados sem reusar uma resposta anterior.',aguardar:true,expected:true,expression:'(async()=>{const dados=[null,0,false,"",[],{},"  texto  ",...Array.from({length:21},(_,i)=>({codigo:i-10,itens:[i,i+1]}))];for(let i=0;i<dados.length;i++){let consultas=0,leituras=0;const dado=dados[i];const resultado=await lerResposta(()=>{consultas++;return Promise.resolve({ok:true,status:[200,201,206,299][i%4],json(){leituras++;return Promise.resolve(dado);}});});if(resultado!==dado||consultas!==1||leituras!==1)return false;}return true;})()',feedback:'Sucesso não exige um valor truthy. Preserve o dado, sua identidade e as chamadas independentes, sem inventar uma lista para substituir vazio ou null.'},
  {label:'Rejeita status HTTP de erro antes de tocar no corpo.',aguardar:true,expected:true,expression:'(async()=>{for(const status of [400,401,403,404,409,429,500,503]){let consultas=0,leituras=0;try{await lerResposta(()=>{consultas++;return Promise.resolve({ok:false,status,json(){leituras++;return Promise.resolve({erro:true});}});});return false;}catch(erro){if(!(erro instanceof Error)||consultas!==1||leituras!==0)return false;}}return true;})()',feedback:'Confira ok antes de json. Mesmo que o corpo seja JSON válido, um status de erro precisa rejeitar com Error, sem consumir o corpo.'},
  {label:'Propaga a falha da obtenção e o cancelamento sem trocar a exceção.',aguardar:true,expected:true,expression:'(async()=>{for(const nome of ["TypeError","AbortError"]){const motivo=new Error("consulta interrompida");motivo.name=nome;let consultas=0;try{await lerResposta(()=>{consultas++;return Promise.reject(motivo);});return false;}catch(erro){if(erro!==motivo||consultas!==1)return false;}}return true;})()',feedback:'Uma falha de transporte ou cancelamento deve chegar ao chamador como o mesmo erro. Retornar uma sentinela ou lançar outro Error perde essa informação.'},
  {label:'Propaga também a rejeição assíncrona ao interpretar o corpo.',aguardar:true,expected:true,expression:'(async()=>{const motivo=new SyntaxError("corpo inválido");let leituras=0;try{await lerResposta(()=>Promise.resolve({ok:true,status:200,json(){leituras++;return Promise.resolve().then(()=>{throw motivo;});}}));return false;}catch(erro){return erro===motivo&&leituras===1;}})()',feedback:'Obter uma resposta não garante um corpo válido. Não engula a falha de json nem devolva sucesso antes de sua conclusão.'},
  {label:'Duas chamadas preservam seus resultados quando a segunda termina primeiro.',aguardar:true,expected:true,expression:'(async()=>{let resolverPrimeira,resolverSegunda,leituras=0,consultasA=0,consultasB=0;const operacaoA=new Promise(r=>{resolverPrimeira=r;}),operacaoB=new Promise(r=>{resolverSegunda=r;});const primeira=lerResposta(()=>{consultasA++;return operacaoA;}),segunda=lerResposta(()=>{consultasB++;return operacaoB;});if(leituras!==0)return false;const a={id:"primeira"},b={id:"segunda"};resolverSegunda({ok:true,status:200,json(){leituras++;return Promise.resolve(b);}});if(await segunda!==b||leituras!==1)return false;resolverPrimeira({ok:true,status:200,json(){leituras++;return Promise.resolve(a);}});return await primeira===a&&leituras===2&&consultasA===1&&consultasB===1;})()',feedback:'Não compartilhe a resposta ou o retorno entre chamadas. A ordem de início não determina a ordem em que cada resultado fica disponível.'}
 ],solution:'async function lerResposta(obter) {\n  const resposta = await obter();\n  if (!resposta.ok) throw new Error("HTTP " + resposta.status);\n  return resposta.json();\n}'},
 'metodos-somar-pares':{checks:[
  check('Todos os pares contribuem, incluindo repetidos.', 'somarPares([1,2,3,4])===6 && somarPares([2,2,3,4])===8 && somarPares([8,3,6,1])===14', 'Conserve os valores que atendem à regra, não suas posições. Repetições continuam contribuindo; contar pares não os soma.'),
  check('Vazio, nenhum par, zero e negativos funcionam.', 'somarPares([])===0 && somarPares([1,3,-5])===0 && somarPares([0])===0 && somarPares([-8,-3,-2,4])===-6 && somarPares([-1000,1000])===0', 'O caso comum passou, mas uma fronteira ainda falha. A seleção pode ficar vazia; negativos pares também pertencem à soma.'),
  check('Outras listas e chamadas independentes conservam a regra.', 'Array.from({length:41},(_,i)=>Array.from({length:i*5},(_,j)=>((j*37+i*13)%2001)-1000)).every(v=>somarPares(v)===v.reduce((s,n)=>n%2===0?s+n:s,0)) && (()=>{const antes=somarPares([2,4]);somarPares([-8,3]);return antes===6 && somarPares([2,4])===6;})()', 'A soma deve acompanhar listas diferentes e recomeçar a cada chamada. Não devolva o exemplo fixo nem acumule estado entre execuções.'),
  check('A entrada permanece intacta depois de cada chamada.', '(()=>{const valores=[4,1,2,-6,3],antes=JSON.stringify(valores);for(let i=0;i<2;i++){if(somarPares(valores)!==0||JSON.stringify(valores)!==antes)return false;}return true;})()', 'Mesmo com o total correto, ordenar, inverter ou remover itens altera a lista do chamador. Confira a entrada logo depois de cada chamada.')
 ],solution:'function somarPares(valores) {\n  return valores.filter(n => n % 2 === 0).reduce((soma,n) => soma + n,0);\n}'},
 'objetos-atualizar-endereco':{checks:[
  check('A cidade muda e os outros campos permanecem.', '(()=>{const pessoa={nome:"Lia",ativo:false,endereco:{cidade:"Recife",cep:"50000",numero:0}};const r=mudarCidade(pessoa,"Natal");return r!==pessoa && r.endereco!==pessoa.endereco && r.nome==="Lia" && r.ativo===false && r.endereco.cidade==="Natal" && r.endereco.cep==="50000" && r.endereco.numero===0;})()', 'Mudar a cidade não deve apagar o nome, dados do endereço ou campos extras. A ficha e seu endereço precisam ser objetos novos.'),
  check('Vazio, cidade igual e outros cadastros são preservados.', '[["","Recife",""],["Bia","Natal","Natal"],["João","São Luís","Belém"]].every(([nome,anterior,cidade])=>{const p={nome,endereco:{cidade:anterior,referencia:"Portão"}};const antes=JSON.stringify(p),r=mudarCidade(p,cidade);return r.nome===nome && r.endereco.cidade===cidade && r.endereco.referencia==="Portão" && r!==p && r.endereco!==p.endereco && JSON.stringify(p)===antes;})', 'Não substitua uma cidade vazia por padrão, não fixe nomes e não reutilize o objeto quando a cidade pedida é igual à anterior.'),
  check('Campos extras variáveis permanecem no cadastro e no endereço.', 'Array.from({length:23},(_,i)=>{const chave="campo"+i,p={nome:"Pessoa "+i,[chave]:i,endereco:{cidade:"Origem "+i,[chave]:i%2===0}},antes=JSON.stringify(p),cidade="Destino "+i,r=mudarCidade(p,cidade);return r!==p && r.endereco!==p.endereco && r.nome===p.nome && r[chave]===i && r.endereco[chave]===(i%2===0) && r.endereco.cidade===cidade && Object.keys(r).sort().join(",")===Object.keys(p).sort().join(",") && Object.keys(r.endereco).sort().join(",")===Object.keys(p.endereco).sort().join(",") && JSON.stringify(p)===antes;}).every(Boolean)', 'Preserve também campos que não aparecem no primeiro exemplo, nos dois níveis. Não reconstrua o cadastro com uma lista fixa de nomes de propriedades.'),
  check('O resultado pode mudar sem alterar o cadastro anterior.', '(()=>{const p={nome:"Lia",endereco:{cidade:"Recife",cep:"50000"}},antes=JSON.stringify(p);const r=mudarCidade(p,"Natal");if(JSON.stringify(p)!==antes)return false;r.nome="Outra";r.endereco.cidade="Manaus";return JSON.stringify(p)===antes;})()', 'A cópia externa passou, mas o endereço ainda pode estar compartilhado. Uma alteração posterior no resultado não pode atingir o cadastro anterior.'),
  check('Chamadas distintas não compartilham o endereço devolvido.', '(()=>{const p=Object.freeze({nome:"Lia",endereco:Object.freeze({cidade:"Recife",cep:"50000"})});const a=mudarCidade(p,"Natal"),b=mudarCidade(p,"Belém");return a!==b && a.endereco!==b.endereco && a.endereco.cidade==="Natal" && b.endereco.cidade==="Belém" && p.endereco.cidade==="Recife" && Object.keys(a).sort().join(",")===Object.keys(p).sort().join(",") && Object.keys(a.endereco).sort().join(",")===Object.keys(p.endereco).sort().join(",");})()', 'Cada atualização precisa fornecer seu próprio resultado, sem escrever na entrada nem reutilizar um endereço guardado por outra chamada.')
 ],solution:'function mudarCidade(pessoa,cidade) {\n  return {...pessoa,endereco:{...pessoa.endereco,cidade}};\n}'},
 'json-validar-nome':{checks:[
  check('Nomes são devolvidos como texto original, sem normalização.', 'lerNome(\'{"nome":"Lia"}\')==="Lia" && lerNome(\'{"nome":"  Ana Maria  ","idade":20}\')==="  Ana Maria  " && lerNome(\'{"nome":""}\')===""', 'O campo string já atende ao contrato. Retorne seu conteúdo exatamente, sem fixar o exemplo, aparar espaços ou rejeitar o nome vazio.'),
  check('JSON válido com estrutura errada é rejeitado.', '["null","[]","{}","3","true",\'"Lia"\',\'{"nome":null}\',\'{"nome":3}\',\'{"nome":false}\',\'{"nome":[]}\',\'{"nome":{}}\'].every(texto=>{try{lerNome(texto);return false;}catch(erro){return erro instanceof Error;}})', 'O parse pode funcionar e ainda produzir null, array, um primitivo ou um campo de outro tipo. Converter o campo para texto esconderia essa falha.'),
  check('Texto fora da gramática também sinaliza falha.', '["","{nome:1}",\'{"nome":"Lia",}\',\'{"nome":"Lia"} lixo\'].every(texto=>{try{lerNome(texto);return false;}catch(erro){return erro instanceof Error;}})', 'A falha do parse deve continuar sendo sinalizada ao chamador. Retornar undefined, null ou uma mensagem não equivale a lançar Error.'),
  check('Outros nomes, caracteres e chamadas independentes funcionam.', 'Array.from({length:31},(_,i)=>"Pessoa "+i+" — "+String.fromCharCode(65+i%26)).concat(["<b>Lia</b>","linha\\nseguinte",String.fromCharCode(34,92),"José"]).every(nome=>lerNome(JSON.stringify({extra:0,nome}))===nome) && lerNome(\'{"nome":"Lia"}\')==="Lia"', 'Use os dados de cada chamada e preserve escapes já interpretados pelo parse. Devolver HTML como texto aqui não autoriza inseri-lo como HTML na interface.')
 ],solution:'function lerNome(texto) {\n  const dado = JSON.parse(texto);\n  if (dado === null || typeof dado !== "object" || Array.isArray(dado) || typeof dado.nome !== "string") throw new Error("Nome fora do contrato");\n  return dado.nome;\n}'},
 'textos-corrigir-entrada':{checks:[
  check('Conversões válidas devolvem o dobro numérico.', 'dobroTexto(" 6 ")===12 && dobroTexto("-2.5")===-5 && dobroTexto("0.125")===0.25 && dobroTexto("+4")===8 && dobroTexto("0")===0 && dobroTexto("1000000")===2000000 && dobroTexto("-1000000")===-2000000', 'Preserve frações, negativos, zero e os limites. Mostrar um valor ou devolvê-lo como texto não fornece o número pedido ao chamador.'),
  check('Ausência e texto inválido são rejeitados com Error.', '([""," \\t\\n","\\u00a0\\ufeff","abc","3px","2,5"].every(texto=>{try{dobroTexto(texto);return false;}catch(erro){return erro instanceof Error;}}))', 'O caso comum funciona, mas ausência ou texto inválido ainda escapa. Zero informado é válido; vazio não é. Uma sentinela ou mensagem devolvida não atende à rejeição pedida.'),
  check('Conversão completa e finitude seguem o contrato.', '[["0x10",32],["0b11",6],["0o10",16],["1e2",200],["-1.25e1",-25],[".5",1],["2.",4]].every(([texto,esperado])=>dobroTexto(texto)===esperado) && ["Infinity","-Infinity","1e309","NaN"].every(texto=>{try{dobroTexto(texto);return false;}catch(erro){return erro instanceof Error;}})', 'Ler só um prefixo muda os formatos aceitos. Um valor infinito também precisa ser rejeitado, mesmo quando não é NaN.'),
  check('Entradas variadas e chamadas independentes são conservadas.', 'Array.from({length:101},(_,i)=>(i-50)/16).every(n=>dobroTexto(" \\t"+n+"\\n")===n*2) && (()=>{const antes=dobroTexto("6");dobroTexto("0");return antes===12 && dobroTexto("6")===12 && dobroTexto("2")+dobroTexto("-1")===2;})()', 'A transformação precisa acompanhar outras entradas e chamadas repetidas, sem respostas fixas, arredondamento ou acúmulo entre conversões.')
 ],solution:'function dobroTexto(texto) {\n  const limpo = texto.trim();\n  if (!limpo) throw new Error("Informe um número");\n  const numero = Number(limpo);\n  if (!Number.isFinite(numero)) throw new Error("Número inválido");\n  return numero * 2;\n}'},
 'erros-corrigir-area':{checks:[
  check('Dimensões distintas e quadrados seguem o contrato.', 'area(4,3)===12 && area(2,5)===10 && area(3,3)===9', 'O programa pode terminar normalmente e ainda calcular outra medida. Compare o significado da operação com a área solicitada.'),
  check('Zero, frações e limites são preservados.', 'area(0,7)===0 && area(7,0)===0 && area(0,0)===0 && area(0.5,3)===1.5 && area(2.5,1.5)===3.75 && area(100,100)===10000', 'O caso comum passou, mas uma dimensão zero, uma fração ou o limite ainda falha. Não arredonde nem substitua zero.'),
  check('Outras dimensões e a troca de orientação conservam a área.', 'Array.from({length:101},(_,i)=>[i,(i*37)%101]).every(([b,h])=>area(b,h)===b*h && area(h,b)===b*h)', 'Não fixe os valores dos exemplos. Trocar base e altura não muda a área, mas dimensões diferentes precisam mudar o resultado.'),
  check('Retornos são numéricos e chamadas não acumulam estado.', '(()=>{const primeira=area(4,3);area(100,1);return primeira===12 && area(4,3)===12 && area(1,2)+area(3,4)===14;})()', 'Mostrar o resultado não o devolve ao chamador. O cálculo também não deve conservar dimensões ou totais de outra chamada.')
 ],solution:'function area(base, altura) { return base * altura; }'},
 'investigar-corrigir-dobro':{checks:[
  check('Positivo e negativo que já funcionavam são preservados.', 'dobro(4)===8 && dobro(-3)===-6', 'Uma correção precisa manter os comportamentos já válidos. Compare o retorno de um positivo e de um negativo.'),
  check('Zero, frações e extremos obedecem à mesma regra.', 'dobro(0)===0 && dobro(0.5)===1 && dobro(-0.25)===-0.5 && dobro(-100)===-200 && dobro(100)===200', 'A fronteira ainda diverge, ou a correção arredondou uma entrada válida. Zero é um número do contrato, não falta de entrada.'),
  check('Outras entradas não dependem de exemplos fixos.', 'Array.from({length:201},(_,i)=>i-100).every(n=>dobro(n)===n*2)', 'Os casos mostrados não esgotam o intervalo. A mesma transformação precisa acompanhar cada entrada.'),
  check('Chamadas independentes devolvem números utilizáveis.', '(()=>{const antes=dobro(0);dobro(9);return antes===0 && dobro(0)===0 && dobro(2)+dobro(-1)===2;})()', 'Um log não substitui return; guardar um resultado anterior também altera a próxima chamada.')
 ],solution:'function dobro(valor) { return valor * 2; }'},
 'colecoes-corrigir-acumulacao':{checks:[
  check('Todas as fichas contribuem, mesmo com nome e quantidade iguais.', 'totalEstoque([{nome:"A",quantidade:2},{nome:"B",quantidade:0},{nome:"A",quantidade:2}])===4 && totalEstoque([{nome:"X",quantidade:7},{nome:"Y",quantidade:3}])===10', 'Guardar apenas a última quantidade, contar fichas ou eliminar repetições perde contribuições. Acompanhe o acumulador após cada item.'),
  check('Vazio, zero, uma ficha e limites produzem números.', 'totalEstoque([])===0 && totalEstoque([{nome:"Zero",quantidade:0}])===0 && totalEstoque([{nome:"Uma",quantidade:9}])===9 && totalEstoque(Array.from({length:100},()=>({nome:"Igual",quantidade:1000})))===100000', 'O caso comum passou, mas o vazio ou uma fronteira ainda falha. O ponto inicial da acumulação precisa funcionar sem visitar nenhum item.'),
  check('Outras coleções conservam cada quantidade.', 'Array.from({length:31},(_,n)=>Array.from({length:n},(_,i)=>({nome:String(i%3),quantidade:(i*37+n)%1001}))).every(itens=>totalEstoque(itens)===itens.reduce((soma,item)=>soma+item.quantidade,0))', 'Nomes repetidos não são uma regra para descartar fichas. Não dependa do tamanho, da ordem ou das quantidades do exemplo.'),
  check('Lista, objetos e chamadas independentes permanecem intactos.', '(()=>{const itens=[{nome:"B",quantidade:5},{nome:"A",quantidade:2},{nome:"B",quantidade:0}],ordem=[...itens],antes=JSON.stringify(itens);const a=totalEstoque(itens);if(a!==7 || JSON.stringify(itens)!==antes || !itens.every((item,i)=>item===ordem[i]))return false;totalEstoque([{nome:"Outro",quantidade:9}]);const b=totalEstoque(itens);return b===7 && JSON.stringify(itens)===antes && itens.every((item,i)=>item===ordem[i]) && totalEstoque([])===0;})()', 'Somar não exige consumir, ordenar ou reescrever o estoque. Confira os objetos originais e repita a chamada depois de uma lista diferente.')
 ],solution:'function totalEstoque(itens) { let total = 0; for (const item of itens) total += item.quantidade; return total; }'},
 'entrada-corrigir-total':{checks:[
  check('Preço por unidade e frete fixo são combinados.', 'calcularTotal(3,1200,700)===4300 && calcularTotal(2,250,100)===600', 'Separe o subtotal por unidades do custo fixo. Um frete aplicado a cada item altera a regra.'),
  check('Zero e os limites do contrato permanecem numéricos.', 'calcularTotal(0,1200,700)===700 && calcularTotal(4,0,700)===700 && calcularTotal(4,250,0)===1000 && calcularTotal(0,0,0)===0 && calcularTotal(100,100000,50000)===10050000', 'O caso comum funciona, mas zero ou uma fronteira ainda falha. Zero não deve ser substituído e a saída não deve ser texto.'),
  check('Entradas variadas seguem a mesma transformação.', 'Array.from({length:101},(_,q)=>[q,(q*193)%100001,(q*71)%50001]).every(([q,p,f])=>calcularTotal(q,p,f)===q*p+f)', 'A regra precisa funcionar com outras quantidades, preços e fretes. Não fixe o exemplo nem descarte um dos parâmetros.'),
  check('Uma chamada não modifica o cálculo da próxima.', '(()=>{const a=calcularTotal(2,500,30);calcularTotal(0,99,7);const b=calcularTotal(2,500,30);return a===1030 && b===1030 && calcularTotal(1,10,0)+calcularTotal(1,20,5)===35;})()', 'O resultado depende das entradas desta chamada, sem acumular totais entre pedidos.')
 ],solution:'function calcularTotal(quantidade, precoUnitario, frete) { return quantidade * precoUnitario + frete; }'},
 'passos-corrigir-media':{checks:[
  check('As três notas participam da média.', conferirMedias('[[7,9,5],[3,4,9]]'), 'A soma pode estar correta enquanto o divisor permanece ligado à versão com duas notas. Confira as duas etapas.'),
  check('Zero, frações e fronteiras não são descartados.', conferirMedias('[[0,0,0],[0,0,9],[10,10,10],[2.5,5,7.5],[0,0,0.75]]'), 'O exemplo passou, mas um caso mínimo ou fracionário ainda falha. Não arredonde nem use zero como ausência.'),
  check('Outras combinações conservam soma e quantidade.', conferirMedias('Array.from({length:41},(_,i)=>[i/4,(40-i)/4,(i%7)/2])'), 'O resultado precisa combinar as três entradas, sem depender da ordem ou das notas do exemplo.'),
  check('Médias são utilizáveis e independentes entre chamadas.', '(()=>{const antes=mediaTres(1,2,3);mediaTres(10,10,10);return antes===2 && mediaTres(1,2,3)===2 && mediaTres(3,3,3)+mediaTres(6,6,6)===9;})()', 'Mostrar um número não o devolve; acumular estado de outra chamada também altera o contrato.')
 ],solution:'function mediaTres(primeira, segunda, terceira) { const soma = primeira + segunda + terceira; return soma / 3; }'},

 'js-debug-conversao-retorno':{checks:[
  check("Conversões comuns devolvem números utilizáveis.","segundos(3)===180 && segundos(2)===120","O console pode mostrar o produto correto, mas confira o valor recebido pelo chamador. A função deve devolver um número utilizável."),
  check("Zero, frações e o limite do contrato são preservados.","segundos(0)===0 && segundos(0.5)===30 && segundos(1.25)===75 && segundos(59.5)===3570 && segundos(1440)===86400","O caso comum funciona, mas zero, frações ou o limite ainda falham. A conversão não deve arredondar minutos nem substituir zero por um padrão."),
  check("Novas entradas seguem a mesma transformação.","Array.from({length:145},(_,indice)=>indice*10).every(minutos=>segundos(minutos)===minutos*60)","Uma resposta fixa ou limitada aos exemplos não acompanha outras entradas do contrato. Observe a relação entre a entrada e o resultado."),
  check("Chamadas independentes podem ser compostas.","(()=>{const primeira=segundos(2);segundos(0);const segunda=segundos(3);return primeira+segunda===300 && segundos(2)===120 && segundos(0)===0;})()","Converter novamente não deve acumular o resultado anterior. Confira duas chamadas separadas e a soma de seus retornos.")
 ],solution:"function segundos(minutos) {\n  return minutos * 60;\n}"},

 'js-debug-faixas-energia':{checks:[
  check('Valores dentro de cada faixa chegam ao ramo esperado.','nivel(10)==="baixa"&&nivel(50)==="média"&&nivel(90)==="alta"','Confira os três ramos e o valor devolvido, sem trocar retorno por saída no console.'),
  check('As fronteiras 20 e 80 pertencem às faixas seguintes.','nivel(19.5)==="baixa"&&nivel(20)==="média"&&nivel(79.5)==="média"&&nivel(80)==="alta"','O exemplo comum funciona, mas uma fronteira ainda caiu na faixa anterior. Compare igualdade e o primeiro retorno alcançado.'),
  check('Extremos e intervalos conservam a classificação.','(()=>{for(let energia=0;energia<=100;energia++){const esperado=energia<20?"baixa":energia<80?"média":"alta";if(nivel(energia)!==esperado)return false;}return nivel(0.1)==="baixa"&&nivel(20.1)==="média"&&nivel(80.1)==="alta";})()','O contrato inclui zero, cem e valores entre exemplos. Não resolva somente as entradas mostradas nem arredonde para escolher uma faixa.'),
  check('Outra chamada não conserva a faixa da anterior.','[90,10,50,80,20,0,100,50].map(energia=>nivel(energia)).join("|")==="alta|baixa|média|alta|média|baixa|alta|média"','Cada chamada precisa depender da energia recebida agora, sem guardar uma classificação anterior.')
 ],solution:'function nivel(energia) {\n  if (energia < 20) return "baixa";\n  if (energia < 80) return "média";\n  return "alta";\n}'},

 'js-debug-saldo-textual':{checks:[
  check('Saldo e ajuste numéricos produzem número somado.','somarSaldo(100,25)===125','O resultado ainda mistura texto e cálculo. Inspecione os operandos no instante da operação e o valor devolvido.'),
  check('Zero é válido em qualquer uma das entradas.','somarSaldo(0,0)===0&&somarSaldo(0,25)===25&&somarSaldo(100,0)===100','Zero não significa entrada ausente. Confira também se outra chamada deixou algum estado acumulado.'),
  check('Ajustes negativos podem reduzir, atravessar zero ou cancelar o saldo.','somarSaldo(100,-125)===-25&&somarSaldo(-50,25)===-25&&somarSaldo(-50,-25)===-75&&somarSaldo(25,-25)===0','O contrato permite resultados negativos e zero; trocar sinais ou limitar o resultado apaga operações válidas.'),
  check('As fronteiras conservam o cálculo e chamadas independentes.','somarSaldo(10000,10000)===20000&&somarSaldo(-10000,-10000)===-20000&&somarSaldo(0,0)===0&&somarSaldo(100,25)===125','O limite descreve cada entrada, não impõe o mesmo teto ao resultado. O próximo cálculo deve começar somente com suas duas entradas.')
 ],solution:'function somarSaldo(saldo, variacao) {\n  return saldo + variacao;\n}'},
 'js-debug-soma-inclusiva':{checks:[
  check('A soma até quatro inclui o último número.','somarAte(4)===10','O intervalo pedido inclui seu último valor. Compare a última comparação com o último número que realmente foi somado.'),
  check('Zero não executa uma passagem fictícia.','somarAte(0)===0','Zero representa um intervalo vazio. O estado inicial deve permitir devolver zero sem inventar um termo.'),
  check('Um inclui exatamente o primeiro termo.','somarAte(1)===1','A menor entrada positiva expõe a fronteira: o primeiro e o último termo são o mesmo número.'),
  check('Outros intervalos produzem somas próprias.','somarAte(2)===3&&somarAte(17)===153&&somarAte(1000)===500500','Confira o resultado devolvido e a continuidade do intervalo. Acertar somente o exemplo não atende às outras entradas.'),
  check('Chamadas intercaladas não conservam a soma anterior.','somarAte(1000)===500500&&somarAte(0)===0&&somarAte(1)===1&&somarAte(4)===10','Uma chamada não deve começar com o total deixado por outra. Investigue onde o acumulador nasce.')
 ],solution:'function somarAte(n) {\n  let total = 0;\n  for (let i = 1; i <= n; i++) {\n    total += i;\n  }\n  return total;\n}'},
 'js-debug-importacao-atomica':{checks:[
  check("Importação válida substitui, recorta espaços e mantém a identidade.","(()=>{const estado=[\"antigo\"],alias=estado;const quantidade=importarNomes(estado,'[ {\"nome\":\" Lia \",\"extra\":true},{\"nome\":\"Caio\"} ]');return quantidade===2&&estado===alias&&JSON.stringify(estado)==='[\"Lia\",\"Caio\"]';})()","Confira a substituição do conteúdo, o retorno e trim; não apenas acrescente os novos nomes."),
  check("Lista vazia é uma importação válida e limpa o conteúdo.","(()=>{const estado=[\"anterior\"];return importarNomes(estado,\"[]\")===0&&estado.length===0;})()","A coleção vazia não é uma falha de arquivo. Ela precisa substituir a lista anterior por zero nomes."),
  check("Registro inválido depois de um válido conserva o estado anterior.","(()=>{const estado=[\"anterior\",\"reserva\"],alias=estado;try{importarNomes(estado,'[ {\"nome\":\"novo\"},null ]');return false;}catch(erro){return erro instanceof TypeError&&estado===alias&&JSON.stringify(estado)==='[\"anterior\",\"reserva\"]';}})()","O caso comum funciona, mas uma falha depois do primeiro registro ainda altera a lista. Investigue a fronteira entre preparar e escrever."),
  check("Estruturas e nomes inválidos não são convertidos ou ignorados.","[\"null\",\"{}\",'[[]]','[{\"nome\":17}]','[{\"nome\":null}]','[{\"nome\":\"   \"}]',\"[{}]\"].every(texto=>{const estado=[\"original\"];try{importarNomes(estado,texto);return false;}catch(erro){return erro instanceof TypeError&&JSON.stringify(estado)==='[\"original\"]';}})","Confira lista, registro e nome antes de escrever. Conversão automática e descarte silencioso de registros não atendem ao contrato."),
  check("O limite inclui 100 registros e recusa 101 sem escrita.","(()=>{const estado=[\"antes\"],cem=Array.from({length:100},(_,i)=>({nome:\"n\"+i}));if(importarNomes(estado,JSON.stringify(cem))!==100||estado[0]!==\"n0\"||estado[99]!==\"n99\")return false;const anterior=JSON.stringify(estado);try{importarNomes(estado,JSON.stringify([...cem,{nome:\"extra\"}]));return false;}catch(erro){return erro instanceof TypeError&&JSON.stringify(estado)===anterior;}})()","A fronteira aceita exatamente 100 registros. Recusar o próximo arquivo não deve apagar a importação válida anterior."),
  check("Parsing inválido preserva SyntaxError e os dados anteriores.","(()=>{const estado=[\"seguro\"];try{importarNomes(estado,\"[{ \");return false;}catch(erro){return erro instanceof SyntaxError&&JSON.stringify(estado)==='[\"seguro\"]';}})()","Não transforme erro de parsing em lista vazia nem esconda a causa. Confira se a limpeza ocorre antes de interpretar o arquivo."),
  check("Uma recusa não bloqueia a próxima importação válida.","(()=>{const estado=[\"antes\"];try{importarNomes(estado,'[{\"nome\":\"parcial\"},null]');}catch{}return importarNomes(estado,'[{\"nome\":\" depois \"}]')===1&&JSON.stringify(estado)==='[\"depois\"]';})()","Depois de uma recusa, uma nova tentativa deve substituir a lista normalmente, sem conservar parcelas do arquivo defeituoso.")
 ],solution:"function importarNomes(estado, texto) {\n  const dados = JSON.parse(texto);\n  if (!Array.isArray(dados) || dados.length > 100) throw new TypeError(\"lista inválida\");\n  const nomes = dados.map(item => {\n    if (!item || typeof item !== \"object\" || Array.isArray(item) || typeof item.nome !== \"string\" || !item.nome.trim()) throw new TypeError(\"registro inválido\");\n    return item.nome.trim();\n  });\n  estado.splice(0, estado.length, ...nomes);\n  return estado.length;\n}"},
 'js-debug-contadores':{checks:[
  check('Uma instância soma e informa seu total.','(()=>{const contador=criarContador(2);return contador.ler()===2 && contador.somar(3)===true && contador.ler()===5;})()','Confira o valor inicial, o retorno booleano de somar e o total depois da operação.'),
  check('Criar e alterar outra instância preserva a anterior.','(()=>{const a=criarContador(2),b=criarContador(10);if(a.ler()!==2||b.ler()!==10)return false;a.somar(3);b.somar(7);const c=criarContador();return a.ler()===5&&b.ler()===17&&c.ler()===0;})()','O caso isolado funciona, mas criar ou alterar outra instância ainda muda o primeiro contador. Investigue o binding compartilhado.'),
  check('Incremento inválido não altera o total.','(()=>{const contador=criarContador(4);for(const valor of [0,-1,1.5,"2",null,undefined,NaN,Infinity,Number.MAX_SAFE_INTEGER+1]){if(contador.somar(valor)!==false||contador.ler()!==4)return false;}return contador.somar(2)===true&&contador.ler()===6;})()','Rejeite incrementos fora do contrato antes de escrever; uma recusa deve conservar o total e permitir operações seguintes.'),
  check('A fronteira segura rejeita overflow sem perder o estado.','(()=>{const contador=criarContador(Number.MAX_SAFE_INTEGER-1);return contador.somar(1)===true&&contador.ler()===Number.MAX_SAFE_INTEGER&&contador.somar(1)===false&&contador.ler()===Number.MAX_SAFE_INTEGER;})()','O incremento pode ser válido e ainda produzir um próximo total inseguro. Confira a condição antes da escrita.'),
  check('Inicial inválido é recusado e métodos destacados conservam a instância.','(()=>{for(const valor of [-1,1.5,"2",null,NaN,Infinity,Number.MAX_SAFE_INTEGER+1]){try{criarContador(valor);return false;}catch(erro){if(!(erro instanceof TypeError))return false;}}const contador=criarContador(7),ler=contador.ler,somar=contador.somar;return somar(2)===true&&ler()===9&&contador.ler()===9;})()','Confira a criação inválida e o acesso pelos métodos destacados; o contrato não depende do receptor da chamada.')
 ],solution:'function criarContador(inicial = 0) {\n  if (!Number.isSafeInteger(inicial) || inicial < 0) throw new TypeError("inicial inválido");\n  let total = inicial;\n  return {\n    somar(valor) {\n      if (!Number.isSafeInteger(valor) || valor <= 0 || !Number.isSafeInteger(total + valor)) return false;\n      total += valor;\n      return true;\n    },\n    ler() { return total; }\n  };\n}'},
 'js-debug-callbacks':{checks:[
  check('Três callbacks executados depois retornam seus índices.','(()=>{const callbacks=criarCallbacks(3);return Array.isArray(callbacks)&&callbacks.length===3&&callbacks.every(funcao=>typeof funcao==="function")&&JSON.stringify(callbacks.map(funcao=>funcao()))==="[0,1,2]";})()','Depois do laço, os callbacks ainda leem o mesmo binding terminal. Investigue qual variável cada função conserva.'),
  check('Zero, um e outras quantidades preservam tamanho e ordem.','[0,1,7,32].every(quantidade=>{const callbacks=criarCallbacks(quantidade);return Array.isArray(callbacks)&&callbacks.length===quantidade&&callbacks.every((funcao,indice)=>typeof funcao==="function"&&funcao()===indice);})','A correção precisa acompanhar a quantidade recebida, inclusive zero, sem fixar as três saídas do exemplo.'),
  check('A chamada pode ocorrer fora de ordem e repetidamente.','(()=>{const callbacks=criarCallbacks(5);return [4,0,2,4,1,0].every(indice=>callbacks[indice]()===indice);})()','Cada callback deve conservar seu próprio índice, sem depender da ordem ou do número de chamadas.'),
  check('Outra fábrica não modifica callbacks anteriores.','(()=>{const anteriores=criarCallbacks(4),novos=criarCallbacks(2);return anteriores[3]()===3&&novos[1]()===1&&anteriores[0]()===0;})()','Chamadas distintas ainda compartilham estado. Investigue onde nascem os bindings capturados.'),
  check('Quantidade fora do contrato lança RangeError.','[-1,33,1.5,"3",null,undefined,NaN,Infinity].every(valor=>{try{criarCallbacks(valor);return false;}catch(erro){return erro instanceof RangeError;}})','Rejeite quantidade inválida antes de construir a coleção; conversão implícita não faz parte deste contrato.')
 ],solution:'function criarCallbacks(quantidade) {\n  if (!Number.isSafeInteger(quantidade) || quantidade < 0 || quantidade > 32) throw new RangeError("quantidade inválida");\n  const callbacks = [];\n  for (let indice = 0; indice < quantidade; indice++) callbacks.push(() => indice);\n  return callbacks;\n}'},
 'js-debug-snapshot':{checks:[
  check('Strings válidas são aparadas, mantendo ordem e duplicatas.','(()=>{const lista=criarLista([" HTML ","CSS","HTML"]);return lista.adicionar(" JS ")===true&&JSON.stringify(lista.snapshot())===\'["HTML","CSS","HTML","JS"]\';})()','Confira trim, retorno da inclusão, ordem e duplicatas; a lista não é um conjunto.'),
  check('Construção e alterações externas preservam as duas coleções.','(()=>{const entrada=[" HTML ","CSS"],lista=criarLista(entrada);if(JSON.stringify(entrada)!==\'[" HTML ","CSS"]\')return false;entrada[0]="mudou";entrada.push("extra");return JSON.stringify(lista.snapshot())===\'["HTML","CSS"]\';})()','A primeira saída funciona, mas a entrada e o estado interno ainda se afetam. Confira a fronteira da construção.'),
  check('Snapshots novos e mutáveis não permitem escrever na instância.','(()=>{const lista=criarLista(["A","B"]),primeiro=lista.snapshot(),segundo=lista.snapshot();if(primeiro===segundo)return false;primeiro[0]="X";primeiro.push("C");segundo.pop();return JSON.stringify(lista.snapshot())===\'["A","B"]\'&&JSON.stringify(primeiro)===\'["X","B","C"]\';})()','Uma saída ainda permite escrever no estado interno ou reutiliza outra saída. Investigue cada referência devolvida.'),
  check('Recusas preservam estado e snapshots antigos.','(()=>{const lista=criarLista(["A"]),antes=lista.snapshot();for(const valor of ["","  ",null,undefined,2,{},[]])if(lista.adicionar(valor)!==false)return false;if(JSON.stringify(lista.snapshot())!==\'["A"]\')return false;return lista.adicionar("B")===true&&JSON.stringify(antes)===\'["A"]\';})()','Recusar uma entrada deve conservar o estado; uma inclusão posterior também não deve reescrever um snapshot anterior.'),
  check('Listas vazias e instâncias distintas são independentes.','(()=>{const a=criarLista(),b=criarLista();a.adicionar("A");return JSON.stringify(a.snapshot())===\'["A"]\'&&Array.isArray(b.snapshot())&&b.snapshot().length===0;})()','Confira o caso vazio e a independência entre duas chamadas da fábrica.'),
  check('Inicial inválido lança TypeError sem modificar a entrada.','[null,{},"A",[" A ",2],[" A "," "],Array(2)].every(entrada=>{const antes=JSON.stringify(entrada);try{criarLista(entrada);return false;}catch(erro){return erro instanceof TypeError&&JSON.stringify(entrada)===antes;}})','Valide todo o formato antes de modificar dados; uma falha na segunda posição não autoriza alterar a primeira.')
 ],solution:'function criarLista(iniciais = []) {\n  if (!Array.isArray(iniciais) || !Array.from(iniciais).every(texto => typeof texto === "string" && texto.trim() !== "")) throw new TypeError("lista inválida");\n  const itens = iniciais.map(texto => texto.trim());\n  return {\n    adicionar(texto) {\n      if (typeof texto !== "string" || texto.trim() === "") return false;\n      itens.push(texto.trim());\n      return true;\n    },\n    snapshot() { return [...itens]; }\n  };\n}'},
 'js-debug-numero-proprio':{checks:[
check("Números próprios finitos preservam zero e negativos.","lerNumeroProprio({saldo:0},\"saldo\")===0 && lerNumeroProprio({saldo:-3},\"saldo\")===-3 && lerNumeroProprio({saldo:Number.MAX_VALUE},\"saldo\")===Number.MAX_VALUE","Confira o retorno numérico, inclusive zero e negativo, sem depender de um valor fixo."),
check("Ausência e herança não são aceitas como dados próprios.","(()=>{return [Object.create({saldo:20}),{}, {saldo:undefined}].every(obj=>{try{lerNumeroProprio(obj,\"saldo\");return false;}catch(e){return e instanceof TypeError;}});})()","O caso comum funciona, mas herança ou ausência ainda entram como se fossem um dado próprio. Confira o descritor do objeto inicial."),
check("Getters são rejeitados sem executar código.","(()=>{let leituras=0;const obj={get saldo(){leituras++;return 20;}};let rejeitou=false;try{lerNumeroProprio(obj,\"saldo\");}catch(e){rejeitou=e instanceof TypeError;}return rejeitou&&leituras===0;})()","A inspeção ainda chama o getter ou o aceita como dado. A validação deve anteceder a leitura do valor."),
check("Tipos inválidos e números não finitos são recusados.","(()=>{const casos=[[{saldo:\"20\"},\"saldo\"],[{saldo:NaN},\"saldo\"],[{saldo:Infinity},\"saldo\"],[null,\"saldo\"],[[],\"length\"],[()=>0,\"saldo\"],[{saldo:1},1],[{saldo:1},Symbol(\"saldo\")]];return casos.every(([obj,chave])=>{try{lerNumeroProprio(obj,chave);return false;}catch(e){return e instanceof TypeError;}});})()","O contrato não permite conversão nem número não finito. Valide também objeto não nulo, não array e chave string."),
check("Chaves próprias especiais e campos não enumeráveis funcionam.","(()=>{const obj=Object.create(null);Object.defineProperty(obj,\"__proto__\",{value:4});Object.defineProperty(obj,\"constructor\",{value:12});Object.defineProperty(obj,\"hasOwnProperty\",{value:7});Object.defineProperty(obj,\"\",{value:0});return lerNumeroProprio(obj,\"__proto__\")===4&&lerNumeroProprio(obj,\"constructor\")===12&&lerNumeroProprio(obj,\"hasOwnProperty\")===7&&lerNumeroProprio(obj,\"\")===0;})()","O nome da chave não cria herança nesse objeto. Use o descritor próprio, sem chamar um método fornecido pela entrada nem exigir enumeração."),
check("A leitura conserva a entrada e as permissões.","(()=>{const obj={saldo:8},antes=JSON.stringify(Object.getOwnPropertyDescriptors(obj)),proto=Object.getPrototypeOf(obj);const valor=lerNumeroProprio(obj,\"saldo\");return valor===8&&JSON.stringify(Object.getOwnPropertyDescriptors(obj))===antes&&Object.getPrototypeOf(obj)===proto;})()","O valor pode estar certo, mas consultar não deve reescrever campos, permissões ou protótipo.")
],solution:"function lerNumeroProprio(objeto, chave) {\n  if (objeto === null || typeof objeto !== \"object\" || Array.isArray(objeto) || typeof chave !== \"string\") {\n    throw new TypeError(\"Objeto e chave fora do contrato\");\n  }\n  const descriptor = Object.getOwnPropertyDescriptor(objeto, chave);\n  if (!descriptor || !Object.hasOwn(descriptor, \"value\") ||\n      typeof descriptor.value !== \"number\" || !Number.isFinite(descriptor.value)) {\n    throw new TypeError(\"Propriedade própria de número finito exigida\");\n  }\n  return descriptor.value;\n}"},
 'js-debug-carrinho':{
  checks:[
   check('O total do carrinho de exemplo é numérico e correto.','typeof totalizar([{preco:29.95,quantidade:2},{preco:30,quantidade:1}]) === "number" && totalizar([{preco:29.95,quantidade:2},{preco:30,quantidade:1}]) === 89.9','O exemplo ainda produz um valor incorreto. Confira o nome das propriedades e o tipo do retorno.'),
   check('Um carrinho vazio tem total zero.','totalizar([]) === 0','O caso comum pode funcionar, mas um carrinho vazio precisa retornar zero.'),
   check('Outros preços, quantidades e quantidade zero funcionam.','totalizar([{preco:7.5,quantidade:3},{preco:999,quantidade:0}]) === 22.5 && totalizar([{preco:0.1,quantidade:3},{preco:0.2,quantidade:1}]) === 0.5','O total precisa acompanhar novas entradas e o arredondamento, sem depender do exemplo inicial.'),
   check('Dados fora do contrato são recusados.','(()=>{ const dados=[[{preco:"10",quantidade:2}],[{preco:4,quantidade:-1}],[{preco:4,quantidade:1.5}],[{preco:Infinity,quantidade:1}],[{preco:NaN,quantidade:1}],[{preco:-1,quantidade:2}],[null],null]; return dados.every(itens=>{try{totalizar(itens);return false;}catch(erro){return erro instanceof TypeError;}}); })()','O cálculo ainda aceita dados fora do contrato. Valide número finito e quantidade inteira não negativa antes de somar.'),
   check('Faixa numérica segura é respeitada.','(()=>{const dados=[[{preco:1,quantidade:Number.MAX_SAFE_INTEGER+1}],[{preco:Number.MAX_VALUE,quantidade:2}],[{preco:Number.MAX_VALUE,quantidade:1},{preco:Number.MAX_VALUE,quantidade:1}],[{preco:Number.MAX_SAFE_INTEGER,quantidade:1}]];return dados.every(itens=>{try{totalizar(itens);return false;}catch(erro){return erro instanceof TypeError;}});})()','A correção ainda ultrapassa a faixa de precisão numérica. Quantidades precisam ser inteiros seguros, e o total arredondado em centavos deve continuar finito e seguro.'),
   check('Os dados de entrada permanecem intactos.','(()=>{const itens=[{preco:9.25,quantidade:2,nome:"A"},{preco:0,quantidade:1}];const antes=JSON.stringify(itens);totalizar(itens);return JSON.stringify(itens)===antes;})()','O retorno pode estar certo, mas calcular o total não deve reescrever o carrinho.')
  ],
  solution:'function totalizar(itens) {\n  if (!Array.isArray(itens)) throw new TypeError("Carrinho deve ser uma lista");\n  let total = 0;\n  for (const item of itens) {\n    if (item === null || typeof item !== "object" ||\n        typeof item.preco !== "number" || !Number.isFinite(item.preco) || item.preco < 0 ||\n        !Number.isSafeInteger(item.quantidade) || item.quantidade < 0) {\n      throw new TypeError("Item fora do contrato");\n    }\n    total += item.preco * item.quantidade;\n  }\n  const centavos = Math.round(total * 100);\n  if (!Number.isFinite(total) || !Number.isSafeInteger(centavos)) {\n    throw new TypeError("Total fora da faixa segura");\n  }\n  return centavos / 100;\n}'
 },
 'js-debug-soma-vazia':{
  checks:[
   check('Uma soma comum funciona.','somaLista([2,3]) === 5','A soma comum ainda está incorreta. Acompanhe o acumulador e cada valor.'),
   check('A lista vazia retorna o elemento neutro.','somaLista([]) === 0','Funciona no caso comum, mas a lista vazia ainda falha. Revise o valor inicial do acumulador.'),
   check('Novos números, negativos e zero são somados.','somaLista([-8,3,0,10]) === 5 && somaLista([0]) === 0 && somaLista([12,7]) === 19','A solução precisa somar os valores recebidos, inclusive negativos, sem fixar o resultado do exemplo.'),
   check('Somar não modifica a lista.','(()=>{const valores=[2,-4,9];const antes=JSON.stringify(valores);somaLista(valores);return JSON.stringify(valores)===antes;})()','O resultado pode estar correto, mas a lista foi modificada.')
  ],solution:'function somaLista(valores) {\n  return valores.reduce((total, valor) => total + valor, 0);\n}'
 },
 'js-debug-maior-negativo':{
  checks:[
   check('O maior elemento funciona no caso comum.','maior([2,9,4]) === 9','O resultado precisa ser o maior elemento recebido.'),
   check('Uma lista de negativos não inventa zero.','maior([-8,-3,-11]) === -3','Funciona com positivos, mas falha quando todos os elementos são negativos. Reveja a inicialização.'),
   check('A lista vazia tem retorno explícito.','maior([]) === null','A lista vazia precisa retornar null, conforme o contrato.'),
   check('Elemento único e novas ordens funcionam.','maior([-9]) === -9 && maior([4,4,1]) === 4 && maior([0,-1]) === 0','Confira um único elemento, empates e a posição do maior valor.'),
   check('Buscar o maior preserva a entrada.','(()=>{const valores=[3,1,7];const antes=JSON.stringify(valores);maior(valores);return JSON.stringify(valores)===antes;})()','A busca não precisa reorganizar nem apagar a lista recebida.')
  ],solution:'function maior(valores) {\n  if (valores.length === 0) return null;\n  let atual = valores[0];\n  for (const valor of valores) {\n    if (valor > atual) atual = valor;\n  }\n  return atual;\n}'
 },
 'js-debug-filtro-mutacao':{
  checks:[
   check('Somente o booleano true passa no filtro.','JSON.stringify(selecionarAtivos([{id:1,ativo:true},{id:2,ativo:false},{id:3,ativo:"true"}]).map(p=>p.id)) === "[1]"','O filtro ainda aceita cadastros cujo ativo não é o booleano true. Revise a comparação.'),
   check('Uma lista vazia continua vazia.','Array.isArray(selecionarAtivos([])) && selecionarAtivos([]).length === 0','Uma entrada vazia precisa devolver uma lista vazia.'),
   check('A seleção acompanha novos dados e preserva a ordem.','JSON.stringify(selecionarAtivos([{id:8,ativo:false},{id:4,ativo:true},{id:2,ativo:true},{id:9}]).map(p=>p.id)) === "[4,2]"','A seleção deve acompanhar outras entradas e manter a ordem original.'),
   check('A filtragem não muda objetos nem a lista.','(()=>{const pessoas=[{id:1,ativo:false,nome:"A"},{id:2,ativo:true,nome:"B"}];const antes=JSON.stringify(pessoas);selecionarAtivos(pessoas);return JSON.stringify(pessoas)===antes;})()','O resultado pode parecer correto, mas o filtro está alterando os cadastros recebidos.')
  ],solution:'function selecionarAtivos(pessoas) {\n  return pessoas.filter(pessoa => pessoa.ativo === true);\n}'
 }
};
export function getPracticeSolution(id:string):string|undefined{
 return concepts[id]?.solution??javascript[id]?.solution??solucoesSql[id];
}
function condicaoDeAusencia(resposta:string):boolean{
 const texto=resposta.trim();
 if(/[^\S \t\f]/.test(texto))return false;
 const partes=texto.match(/[A-Za-z_]\w*|[()]|\S/g)??[];
 if(partes.length>128||partes.some(parte=>!['valor','vistos','not','in','(',')'].includes(parte)))return false;
 let alterou=true;
 while(alterou){
  alterou=false;
  for(let indice=0;indice<partes.length;indice++){
   const atual=partes[indice],proxima=partes[indice+1];
   let tamanho=0,resultado='';
   if(atual==='('&&['valor','vistos','presente','ausente'].includes(proxima)&&partes[indice+2]===')'){
    tamanho=3;resultado=proxima;
   }else if(atual==='valor'&&proxima==='not'&&partes[indice+2]==='in'&&partes[indice+3]==='vistos'){
    tamanho=4;resultado='ausente';
   }else if(atual==='valor'&&proxima==='in'&&partes[indice+2]==='vistos'){
    tamanho=3;resultado='presente';
   }else if(atual==='not'&&(proxima==='presente'||proxima==='ausente')){
    tamanho=2;resultado=proxima==='presente'?'ausente':'presente';
   }
   if(tamanho){partes.splice(indice,tamanho,resultado);alterou=true;break;}
  }
 }
 return partes.length===1&&partes[0]==='ausente';
}
function normalized(value:string):string{return value.replace(/\r\n?/g,'\n').trim();}
function base(activity?:PracticeActivity):PracticeResult{
 return {passed:false,status:'evaluated',feedback:'',tests:[],evidence:'conceptual',execution:'not-run',skillIds:activity?[...activity.skillIds]:[],capability:activity?.capability??'reconhecimento'};
}
function cancelled(activity?:PracticeActivity):PracticeResult{
 return {...base(activity),status:'cancelled',feedback:'Verificação cancelada. Seu trabalho continua preservado.'};
}
export async function evaluatePractice(id:string,answer:PracticeAnswer,signal?:AbortSignal):Promise<PracticeResult>{
 const activity=practiceActivities.find(item=>item.id===id);
 if(signal?.aborted)return cancelled(activity);
 if(!activity)return {...base(),status:'unavailable',feedback:'Esta atividade não está disponível nesta versão.'};
 const result=base(activity);
 if(typeof answer!=='string'&&(!Array.isArray(answer)||answer.some(line=>typeof line!=='string')))return {...result,status:'unavailable',feedback:'O formato da resposta não pôde ser lido. Seu trabalho está preservado; isso não conta como erro de aprendizagem.'};
 if((typeof answer==='string'&&answer.length>30000)||(Array.isArray(answer)&&(answer.length>100||answer.some(line=>typeof line!=='string'||line.length>30000)))){
  return {...result,feedback:'A resposta ultrapassou o limite da atividade. Reduza o texto antes de conferir.',tests:[{label:'Resposta dentro do limite.',passed:false}]};
 }
 if(Object.hasOwn(solucoesSql,id)){
  if(typeof answer!=='string')return {...result,feedback:'Envie a consulta SQL completa como texto.',tests:[{label:'Consulta completa recebida.',passed:false}]};
  const inicioCarga=performance.now();let prazo:ReturnType<typeof setTimeout>|undefined;
  let cancelarCarga:(()=>void)|undefined;
  try{
   const limite=new Promise<never>((_,rejeitar)=>{cancelarCarga=()=>rejeitar(new Error('Carga cancelada.'));signal?.addEventListener('abort',cancelarCarga,{once:true});prazo=setTimeout(()=>rejeitar(new Error('Carga expirada.')),20000);});
   const modulo=await Promise.race([import('./pratica-sql'),limite]);
   if(signal?.aborted)return cancelled(activity);
   return await modulo.avaliarPraticaSql(id,answer,result,signal,Math.max(1,20000-(performance.now()-inicioCarga)));
  }catch{
   if(signal?.aborted)return cancelled(activity);
   return {...result,status:'unavailable',feedback:'Não foi possível carregar a conferência SQL no prazo. Sua consulta foi preservada; isso não conta como erro de aprendizagem. Conecte à internet para o primeiro carregamento e tente novamente.'};
  }finally{clearTimeout(prazo);if(cancelarCarga)signal?.removeEventListener('abort',cancelarCarga);}
 }
 const concept=concepts[id];
 if(concept){
  let passed=false;
  if(concept.order){
   let submitted:string[];
   if(Array.isArray(answer))submitted=answer.map(normalized);
   else submitted=normalized(answer).split('\n').map(normalized).filter(Boolean);
   // Require every line exactly once; a prefix, duplicate or injected line cannot pass.
   passed=submitted.length===concept.order.length&&submitted.every((line,index)=>line===concept.order![index]);
  }else if(id==='py-preservar-primeira-ordem')passed=typeof answer==='string'&&condicaoDeAusencia(answer);
  else if(id==='cs-copiar-linhas-array')passed=typeof answer==='string'&&/^linha\s*\.\s*ToArray\s*(?:<\s*(?:int|System\s*\.\s*Int32)\s*>)?\s*\(\s*\)$/.test(normalized(answer));
  else if(id==='cs-materializar-consulta')passed=typeof answer==='string'&&/^To(?:Array|List)\s*\(\s*\)$/.test(normalized(answer));
  else if(id==='py-esperar-vaga-fila')passed=typeof answer==='string'&&/^await[ \t]+fila[ \t]*\.[ \t]*put[ \t]*\([ \t]*item[ \t]*\)$/.test(normalized(answer));
  else if(id==='py-validar-digitos-ascii')passed=typeof answer==='string'&&/^(['"])0\1\s*<=\s*caractere\s*<=\s*(['"])9\2$/.test(normalized(answer));
  else if(id==='sql-correlacionar-ausentes')passed=typeof answer==='string'&&/^IS\s+NOT\s+DISTINCT\s+FROM$/i.test(normalized(answer));
  else passed=typeof answer==='string'&&concept.accepted.includes(normalized(answer));
  result.passed=passed;
  result.tests=[{label:concept.order?'Todas as linhas respeitam a estrutura solicitada.':'A resposta corresponde ao contrato da atividade.',passed}];
  result.feedback=(passed?'Sua resposta está correta. ':concept.failure+' ')+'Esta atividade comprova uma decisão conceitual; não houve execução de '+activity.language+'.';
  return result;
 }
 const spec=javascript[id];
 if(!spec||typeof answer!=='string')return {...result,feedback:'Envie o código completo como texto para conferir o comportamento.',tests:[{label:'Código completo recebido.',passed:false}]};
 let stop:(()=>void)|undefined;
 const abort=()=>stop?.();
 signal?.addEventListener('abort',abort,{once:true});
 try{
  let run:RunResult;
  if(typeof window!=='undefined'&&typeof Worker!=='undefined'){
   const {execute}=await import('../execution/runner');
   if(signal?.aborted)return cancelled(activity);
   const job=execute(answer,'aula',spec.checks);stop=job.cancel;
   run=await job.result;
  }else{
   // Node unit tests have no browser worker; the same isolated WASM evaluator runs.
   const {evaluate}=await import('../execution/evaluate');
   if(signal?.aborted)return cancelled(activity);
   run=await evaluate(answer,'aula',spec.checks);
  }
  if(signal?.aborted)return cancelled(activity);
  if(run.error&&['O executor não carregou. Verifique sua conexão e tente novamente.','Não foi possível iniciar o ambiente de execução. Tente novamente.'].includes(run.error)){
   return {...result,status:'unavailable',feedback:'O ambiente de execução não iniciou. Seu código foi preservado; este problema não conta como erro de aprendizagem.'};
  }
  const tests=run.tests.length?run.tests:[{label:'O programa precisa terminar sem erro.',passed:false}];
  const failed=tests.find(test=>!test.passed);
  const feedback=run.error??spec.checks.find(item=>item.label===failed?.label)?.feedback;
  return {...result,passed:run.passed,evidence:'executed',execution:'quickjs',tests,
   feedback:run.passed?'A correção passou no exemplo e nos casos adicionais deste exercício. Isso comprova os comportamentos testados; não é uma prova formal para todas as entradas.':feedback??'Ainda há uma diferença de comportamento. Investigue a primeira verificação que falhou; a solução continua disponível apenas quando você solicitar.'};
 }catch{
  if(signal?.aborted)return cancelled(activity);
  return {...result,status:'unavailable',feedback:'Não foi possível iniciar a verificação. Seu código está preservado; isso não conta como erro de aprendizagem.'};
 }finally{signal?.removeEventListener('abort',abort);}
}
